// ---------------------------------------------------------------------------
// 13. countriesCapitalsData — 195 countries mapped to capitals
// ---------------------------------------------------------------------------
export function countriesCapitalsData() {
  return worldCountriesData().map(c => ({ country: c.name, capital: c.capital, code: c.code }));
}

// ---------------------------------------------------------------------------
// 14. countryCallingCodesData — 195 countries with calling codes
// ---------------------------------------------------------------------------
export function countryCallingCodesData() {
  return worldCountriesData().map(c => {
    const flagBase = 127397;
    const flag = c.code.toUpperCase().split('').map(ch => String.fromCodePoint(ch.charCodeAt(0) + flagBase)).join('');
    return { country: c.name, code: c.code, callingCode: c.callingCode, flag };
  });
}

